public class TableClothGameTests {
    private static final BlockPos S=new BlockPos(1,2,2),T=new BlockPos(3,2,4),C=new BlockPos(6,3,4);
    private record Fixture(Player player,StockTickerBlockEntity ticker,TableClothBlockEntity cloth,BarrelBlockEntity barrel,PackagerBlockEntity packager){}
    private static BigItemStack item(Item item,int count){return new BigItemStack(new ItemStack(item),count);}
    private static Fixture fixture(GameTestHelper h){
        h.setBlock(S.north(),Blocks.BARREL);var barrel=h.getBlockEntity(S.north(),BarrelBlockEntity.class);barrel.setItem(0,new ItemStack(Items.APPLE,32));h.setBlock(S,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));h.setBlock(S.above(),AllBlocks.STOCK_LINK);var link=h.getBlockEntity(S.above(),PackagerLinkBlockEntity.class);var network=UUID.randomUUID();link.behaviour.setFrequency(network);link.initialize();
        h.setBlock(T,AllBlocks.STOCK_TICKER);h.setBlock(T.west(),AllBlocks.BLAZE_BURNER.defaultBlockState().setValue(com.simibubi.create.content.processing.burner.BlazeBurnerBlock.HEAT_LEVEL,com.simibubi.create.content.processing.burner.BlazeBurnerBlock.HeatLevel.SMOULDERING));var ticker=h.getBlockEntity(T,StockTickerBlockEntity.class);ticker.behaviour.setFrequency(network);
        h.setBlock(C,AllBlocks.TABLE_CLOTHS.get(DyeColor.RED).defaultBlockState().setValue(TableClothBlock.HAS_BE,true));var cloth=h.getBlockEntity(C,TableClothBlockEntity.class);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(ticker.getBlockPos()).add(0,0,1));player.getInventory().setItem(1,new ItemStack(Items.DIAMOND,8));cloth.owner=UUID.randomUUID();cloth.requestData=new AutoRequestData(PackageOrderWithCrafts.simple(List.of(item(Items.APPLE,4))),"Shop",ticker.getBlockPos().subtract(cloth.getBlockPos()),h.getLevel().dimension().identifier().toString(),true);cloth.priceTag.setFilter(new ItemStack(Items.DIAMOND));cloth.priceTag.setAmount(2,false);return new Fixture(player,ticker,cloth,barrel,h.getBlockEntity(S,PackagerBlockEntity.class));
    }
    private static ItemStack list(Fixture f,int count){return ShoppingListItem.saveList(new ItemStack(AllItems.SHOPPING_LIST),new ShoppingListItem.ShoppingList(List.of(new ShoppingListItem.Purchase(count,f.cloth.getBlockPos())),f.cloth.owner,f.ticker.behaviour.freqId),"Shop");}
    private static int payments(Fixture f){return f.ticker.receivedPayments.inputs.stream().filter(slot->slot.getResource().getItem()==Items.DIAMOND).mapToInt(slot->(int)slot.getAmount()).sum();}
    @GameTest public void allNineteenClothsHaveSourceShapesAndOnlyOccupiedStatesCreateBlockEntities(GameTestHelper h){
        h.assertValueEqual(AllBlocks.tableCloths().length,19,"Sixteen dyes and three covers");var pos=new BlockPos(2,2,2);for(var block:AllBlocks.tableCloths()){h.setBlock(pos,block);h.assertTrue(h.getLevel().getBlockEntity(h.absolutePos(pos))==null,"Empty cloth has no block entity");var state=block.defaultBlockState();h.assertValueEqual(state.getCollisionShape(h.getLevel(),h.absolutePos(pos)).max(Direction.Axis.Y),1/16.,"One-pixel collision");h.assertTrue(state.getShape(h.getLevel(),h.absolutePos(pos)).min(Direction.Axis.Y)<0,"Source hanging outline below base");h.setBlock(pos,state.setValue(TableClothBlock.HAS_BE,true));h.assertTrue(h.getLevel().getBlockEntity(h.absolutePos(pos)) instanceof TableClothBlockEntity,"Occupied cloth owns entity");}h.succeed();
    }
    @GameTest public void displayOwnsFourSingleItemsAndRemovesEntityAfterLastRetrieval(GameTestHelper h){
        var pos=new BlockPos(3,2,3);h.setBlock(pos,AllBlocks.TABLE_CLOTHS.get(DyeColor.BLUE).defaultBlockState().setValue(TableClothBlock.HAS_BE,true));var cloth=h.getBlockEntity(pos,TableClothBlockEntity.class);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.APPLE,5));for(int i=0;i<5;i++)cloth.use(player);
        h.assertValueEqual(cloth.manuallyAddedItems.size(),4,"Display accepts at most four");h.assertValueEqual(player.getMainHandItem().getCount(),1,"Exactly four real items consumed");for(int i=0;i<4;i++){player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);cloth.use(player);h.assertTrue(player.getMainHandItem().is(Items.APPLE)&&player.getMainHandItem().getCount()==1,"Real display item retrieved");}h.assertTrue(h.getLevel().getBlockEntity(cloth.getBlockPos())==null&&!h.getBlockState(pos).getValue(TableClothBlock.HAS_BE),"Last retrieval removes unnecessary entity");h.succeed();
    }
    @GameTest public void priceIsOwnerOnlyAndSupportsOneHundredEvenForNonstackableCurrency(GameTestHelper h){
        var f=fixture(h);f.player.setPos(Vec3.atCenterOf(f.cloth.getBlockPos()));f.cloth.owner=f.player.getUUID();f.player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_SWORD));
        h.assertTrue(FilteringSettings.apply(h.getLevel(),f.player,new FilteringSettings.SetFilter(f.cloth.getBlockPos(),Direction.SOUTH,InteractionHand.MAIN_HAND,0,false)),"Owner selects price sample");h.assertValueEqual(f.player.getMainHandItem().getCount(),1,"Sample is not consumed");h.assertTrue(FilteringSettings.apply(h.getLevel(),f.player,new FilteringSettings.SetFilter(f.cloth.getBlockPos(),Direction.SOUTH,InteractionHand.MAIN_HAND,100,false)),"Price reaches source board limit");h.assertValueEqual(f.cloth.getPaymentAmount(),100,"Nonstackable price can exceed one");f.cloth.owner=UUID.randomUUID();h.assertFalse(FilteringSettings.apply(h.getLevel(),f.player,new FilteringSettings.SetFilter(f.cloth.getBlockPos(),Direction.SOUTH,InteractionHand.MAIN_HAND,1,false)),"Other player cannot change price");h.assertFalse(f.cloth.priceTag.setFilter(new ItemStack(AllItems.FILTER)),"Filter item cannot be currency");h.assertFalse(f.cloth.priceTag.setFilter(new ItemStack(AllItems.SHOPPING_LIST)),"Shopping list cannot be currency");h.succeed();
    }
    @GameTest public void clothCreatesImmutableListAndBakesCurrentGoodsAndPayment(GameTestHelper h){
        var f=fixture(h);f.player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);f.cloth.useShop(f.player);var first=ShoppingListItem.getList(f.player.getMainHandItem());f.cloth.useShop(f.player);var second=ShoppingListItem.getList(f.player.getMainHandItem());h.assertValueEqual(first.getPurchases(f.cloth.getBlockPos()),1,"Previous component remains immutable");h.assertValueEqual(second.getPurchases(f.cloth.getBlockPos()),2,"Second use adds a purchase");var baked=second.bakeEntries(h.getLevel(),null);h.assertTrue(baked.valid(),"Shop and keeper validate");h.assertValueEqual(baked.goods().getCountOf(new ItemStack(Items.APPLE)),8,"Two four-apple orders");h.assertValueEqual(baked.payments().getCountOf(new ItemStack(Items.DIAMOND)),4,"Two prices");h.assertValueEqual(ShoppingListItem.getAddress(f.player.getMainHandItem()),"Shop","Encoded shop address");h.succeed();
    }
    @GameTest public void otherShopsOnListReserveSharedStockAndLimitWholeTrades(GameTestHelper h){
        var f=fixture(h);f.barrel.setItem(0,new ItemStack(Items.APPLE,10));GlobalLogisticsManager.get(h.getLevel()).invalidate(f.ticker.behaviour.freqId);var second=C.south();h.setBlock(second,AllBlocks.TABLE_CLOTHS.get(DyeColor.GREEN).defaultBlockState().setValue(TableClothBlock.HAS_BE,true));var other=h.getBlockEntity(second,TableClothBlockEntity.class);other.owner=f.cloth.owner;other.requestData=new AutoRequestData(PackageOrderWithCrafts.simple(List.of(item(Items.APPLE,3))),"Shop",f.ticker.getBlockPos().subtract(other.getBlockPos()),h.getLevel().dimension().identifier().toString(),true);other.priceTag.setFilter(new ItemStack(Items.DIAMOND));f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,1));other.useShop(f.player);other.useShop(f.player);other.useShop(f.player);var list=ShoppingListItem.getList(f.player.getMainHandItem());h.assertValueEqual(list.getPurchases(other.getBlockPos()),2,"Third trade cannot reuse the first cloth's four apples");h.assertValueEqual(list.bakeEntries(h.getLevel(),null).goods().getCountOf(new ItemStack(Items.APPLE)),10,"Exact shared stock");h.succeed();
    }
    @GameTest public void successfulPurchasePaysOnceCreatesRealAddressedParcelAndConsumesList(GameTestHelper h){
        var f=fixture(h);f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,2));h.assertTrue(ShopTrade.purchase(f.player,f.ticker),"Purchase succeeds");h.assertValueEqual(f.barrel.getItem(0).getCount(),24,"Eight apples removed");h.assertValueEqual(f.player.getInventory().getItem(1).getCount(),4,"Four diamonds paid");h.assertValueEqual(payments(f),4,"Register owns payment");h.assertTrue(f.player.getMainHandItem().isEmpty(),"List consumed once");h.assertValueEqual(PackageItem.getAddress(f.packager.heldBox),"Shop","Real parcel address");h.assertValueEqual(PackageItem.getContents(f.packager.heldBox).stream().mapToInt(ItemStack::getCount).sum(),8,"Actual purchased goods boxed");h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"Cannot reuse consumed list");h.succeed();
    }
    @GameTest public void insufficientFundsRollBackRegisterGoodsAndList(GameTestHelper h){
        var f=fixture(h);f.player.getInventory().setItem(1,new ItemStack(Items.DIAMOND,1));var list=list(f,1);f.player.setItemInHand(InteractionHand.MAIN_HAND,list);h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"Insufficient payment refused");h.assertValueEqual(payments(f),0,"Tentative payment insertion rolled back");h.assertValueEqual(f.barrel.getItem(0).getCount(),32,"All goods retained");h.assertValueEqual(f.player.getInventory().getItem(1).getCount(),1,"Partial debit rolled back");h.assertTrue(f.player.getMainHandItem()==list&&f.packager.heldBox.isEmpty(),"List and empty output retained");h.succeed();
    }
    @GameTest public void fullRegisterRollsBackPartialCurrencyInsertion(GameTestHelper h){
        var f=fixture(h);try(var tx=Transaction.openOuter()){f.ticker.receivedPayments.inputs.getFirst().insert(ItemVariant.of(Items.DIAMOND),63,tx);for(int i=1;i<27;i++)f.ticker.receivedPayments.inputs.get(i).insert(ItemVariant.of(Items.STONE),64,tx);tx.commit();}f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,1));h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"No room for both diamonds");h.assertValueEqual(payments(f),63,"One tentative diamond was rolled back");h.assertValueEqual(f.player.getInventory().getItem(1).getCount(),8,"Buyer not charged");h.assertValueEqual(f.barrel.getItem(0).getCount(),32,"Stock retained");h.succeed();
    }
    @GameTest public void registerCanMergePaymentWithoutRequiringEmptySlots(GameTestHelper h){
        var f=fixture(h);try(var tx=Transaction.openOuter()){f.ticker.receivedPayments.inputs.getFirst().insert(ItemVariant.of(Items.DIAMOND),62,tx);for(int i=1;i<27;i++)f.ticker.receivedPayments.inputs.get(i).insert(ItemVariant.of(Items.STONE),64,tx);tx.commit();}f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,1));h.assertTrue(ShopTrade.purchase(f.player,f.ticker),"Exact remaining capacity accepts payment");h.assertValueEqual(payments(f),64,"Payment merged into existing stack");h.succeed();
    }
    @GameTest public void stockChangeAfterEarlierSummaryCannotChargeForUnavailableGoods(GameTestHelper h){
        var f=fixture(h);f.ticker.getAccurateSummary();f.barrel.setItem(0,new ItemStack(Items.APPLE,1));f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,1));h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"Fresh same-tick stock required");h.assertValueEqual(payments(f),0,"No money collected");h.assertTrue(f.player.getMainHandItem().is(AllItems.SHOPPING_LIST)&&f.packager.heldBox.isEmpty(),"Unfulfilled list and no parcel");h.succeed();
    }
    @GameTest public void refusalAfterPartialPackingRollsBackParcelsStockCurrencyAndList(GameTestHelper h){
        var f=fixture(h);f.barrel.setItem(0,new ItemStack(Items.APPLE,4));f.barrel.setItem(1,new ItemStack(Items.DIAMOND));f.cloth.requestData=new AutoRequestData(PackageOrderWithCrafts.simple(List.of(item(Items.APPLE,4),item(Items.DIAMOND,1))),"Shop",f.cloth.requestData.targetOffset(),f.cloth.requestData.targetDim(),true);var touched=new AtomicInteger();var backing=ContainerStorage.of(f.barrel,null);
        ItemStorage.SIDED.registerForBlockEntity((entity,side)->entity==f.barrel?new Storage<ItemVariant>(){
            @Override public long insert(ItemVariant item,long amount,TransactionContext tx){return backing.insert(item,amount,tx);}
            @Override public long extract(ItemVariant item,long amount,TransactionContext tx){if(item.getItem()==Items.DIAMOND)return 0;if(item.getItem()==Items.APPLE)touched.incrementAndGet();return backing.extract(item,amount,tx);}
            @Override public Iterator<StorageView<ItemVariant>> iterator(){return backing.iterator();}
        }:null,BlockEntityTypes.BARREL);
        try(var transaction=Transaction.openOuter()){h.assertFalse(LogisticsManager.dispatchPurchase(h.getLevel(),f.ticker.behaviour.freqId,f.cloth.requestData.encodedRequest(),"Shop",transaction),"Atomic dispatch reports refusal");transaction.commit();}
        h.assertTrue(f.packager.heldBox.isEmpty()&&f.barrel.getItem(0).getCount()==4,"Refused dispatch is rolled back even when caller commits its enclosing transaction");
        f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,1));h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"Second material refuses actual extraction");h.assertTrue(touched.get()>0,"First material was tentatively packed");h.assertValueEqual(f.barrel.getItem(0).getCount(),4,"First extraction rolled back");h.assertTrue(f.packager.heldBox.isEmpty()&&f.packager.queuedExitingPackages.isEmpty(),"Tentative output parcel rolled back");h.assertValueEqual(payments(f),0,"Register rolled back");h.assertValueEqual(f.player.getInventory().getItem(1).getCount(),8,"Buyer debit rolled back");h.assertTrue(f.player.getMainHandItem().is(AllItems.SHOPPING_LIST),"List restored");h.succeed();
    }
    @GameTest public void atomicPurchaseCanSpanMultipleCorrectlyNumberedPackageFragments(GameTestHelper h){
        var f=fixture(h);for(int i=0;i<11;i++)f.barrel.setItem(i,new ItemStack(Items.APPLE,64));f.cloth.requestData=new AutoRequestData(PackageOrderWithCrafts.simple(List.of(item(Items.APPLE,640))),"Shop",f.cloth.requestData.targetOffset(),f.cloth.requestData.targetDim(),true);f.player.setItemInHand(InteractionHand.MAIN_HAND,list(f,1));h.assertTrue(ShopTrade.purchase(f.player,f.ticker),"Large purchase committed");h.assertValueEqual(f.packager.queuedExitingPackages.size(),1,"Second fragment waits");var first=f.packager.heldBox;var second=f.packager.queuedExitingPackages.getFirst().stack;h.assertValueEqual(PackageItem.getIndex(first),0,"First fragment index");h.assertValueEqual(PackageItem.getIndex(second),1,"Second fragment index");h.assertTrue(!PackageItem.isFinal(first)&&PackageItem.isFinal(second),"Only final fragment closes the order");h.assertValueEqual(PackageItem.getContents(first).stream().mapToInt(ItemStack::getCount).sum()+PackageItem.getContents(second).stream().mapToInt(ItemStack::getCount).sum(),640,"All goods represented once");h.assertValueEqual(payments(f),2,"One price for one large purchase");h.succeed();
    }
    @GameTest public void forgedShopOwnerMissingShopAndOverflowCannotBecomePurchases(GameTestHelper h){
        var f=fixture(h);var valid=ShoppingListItem.getList(list(f,1));var forged=new ShoppingListItem.ShoppingList(valid.purchases(),UUID.randomUUID(),valid.shopNetwork());f.player.setItemInHand(InteractionHand.MAIN_HAND,ShoppingListItem.saveList(new ItemStack(AllItems.SHOPPING_LIST),forged,"Shop"));h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"Owner cannot be forged");var huge=valid.withPurchases(f.cloth.getBlockPos(),BigItemStack.INF);h.assertFalse(huge.bakeEntries(h.getLevel(),null).valid(),"Multiplied quantities cannot overflow");h.setBlock(C,Blocks.AIR);h.assertFalse(valid.bakeEntries(h.getLevel(),null).valid(),"Missing shop does not silently become a partial order");h.assertValueEqual(payments(f),0,"No rejected list was charged");h.succeed();
    }
    @GameTest public void savedShopAndShoppingListCodecsPreserveOwnerPriceAddressAndRequest(GameTestHelper h){
        var f=fixture(h);var tag=f.cloth.saveWithFullMetadata(h.getLevel().registryAccess());var loaded=BlockEntity.loadStatic(f.cloth.getBlockPos(),f.cloth.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(loaded instanceof TableClothBlockEntity,"Native block entity reload");var cloth=(TableClothBlockEntity)loaded;h.assertValueEqual(cloth.owner,f.cloth.owner,"Owner persisted");h.assertValueEqual(cloth.getPaymentAmount(),2,"Price persisted");h.assertValueEqual(cloth.requestData.encodedTargetAddress(),"Shop","Address persisted");var buffer=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ItemStack.STREAM_CODEC.encode(buffer,list(f,3));var decoded=ItemStack.STREAM_CODEC.decode(buffer);h.assertValueEqual(ShoppingListItem.getList(decoded).getPurchases(f.cloth.getBlockPos()),3,"Purchase component crosses native item codec");h.assertValueEqual(ShoppingListItem.getAddress(decoded),"Shop","Address component crosses codec");}finally{buffer.release();}h.succeed();
    }
    @GameTest public void keeperProgramsClothThenPlacementAndDropsPreserveAbsoluteTarget(GameTestHelper h){
        var f=fixture(h);var block=AllBlocks.TABLE_CLOTHS.get(DyeColor.BLUE);f.player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(block,2));var menu=new StockTickerMenu(14,f.player.getInventory(),new StockTickerMenu.Opening(f.ticker.getBlockPos(),f.ticker.getUpdateTag(h.getLevel().registryAccess()),false,false,false));var order=PackageOrderWithCrafts.simple(List.of(item(Items.APPLE,4)));
        h.assertTrue(menu.request(f.player,new StockTickerMenu.Request(14,order,"Programmed shop",true)),"Stock Ticker accepts held cloth programming");var programmed=f.player.getMainHandItem().copy();h.assertTrue(programmed.has(AllDataComponents.AUTO_REQUEST_DATA)&&programmed.getCount()==2,"Whole cloth stack receives source program");h.setBlock(C,block);block.setPlacedBy(h.getLevel(),h.absolutePos(C),h.getBlockState(C),f.player,programmed);var cloth=h.getBlockEntity(C,TableClothBlockEntity.class);h.assertValueEqual(cloth.owner,f.player.getUUID(),"Actual placer owns shop");h.assertTrue(cloth.getTicker()==f.ticker,"Absolute target converted to placed relative offset");var drops=Block.getDrops(cloth.getBlockState(),h.getLevel(),cloth.getBlockPos(),cloth);var data=drops.getFirst().get(AllDataComponents.AUTO_REQUEST_DATA);h.assertTrue(data!=null&&data.targetOffset().equals(f.ticker.getBlockPos()),"Dropped shop restores absolute keeper position");h.assertValueEqual(data.encodedTargetAddress(),"Programmed shop","Drop preserves delivery address");h.succeed();
    }
    @GameTest public void shoppingListPurchaseCodecRetainsSourceIntAttachedFieldNames(GameTestHelper h){
        var f=fixture(h);var value=ShoppingListItem.getList(list(f,2));var encoded=ShoppingListItem.ShoppingList.CODEC.encodeStart(com.mojang.serialization.JsonOps.INSTANCE,value).getOrThrow().getAsJsonObject();var purchase=encoded.getAsJsonArray("purchases").get(0).getAsJsonObject();h.assertTrue(purchase.has("first")&&purchase.has("second"),"Original IntAttached record fields retained");var decoded=ShoppingListItem.ShoppingList.CODEC.parse(com.mojang.serialization.JsonOps.INSTANCE,encoded).getOrThrow();h.assertValueEqual(decoded,value,"Source-form component round trip");h.succeed();
    }
    @GameTest public void removingDisplayDropsEachRealItemExactlyOnce(GameTestHelper h){
        var pos=new BlockPos(3,2,3);h.setBlock(pos,AllBlocks.COPPER_TABLE_CLOTH.defaultBlockState().setValue(TableClothBlock.HAS_BE,true));var cloth=h.getBlockEntity(pos,TableClothBlockEntity.class);cloth.manuallyAddedItems.add(new ItemStack(Items.DIAMOND));cloth.manuallyAddedItems.add(new ItemStack(Items.EMERALD));h.getLevel().destroyBlock(cloth.getBlockPos(),false);var area=new AABB(cloth.getBlockPos()).inflate(1);var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,area);h.assertValueEqual(drops.stream().mapToInt(entity->entity.getItem().getCount()).sum(),2,"Only two owned display items returned");h.assertTrue(cloth.manuallyAddedItems.isEmpty(),"Removed entity no longer owns items");h.succeed();
    }
    @GameTest public void refusedShopInteractionKeepsExistingListAndWrongNetworkCannotCharge(GameTestHelper h){
        var f=fixture(h);var held=list(f,1);f.player.setItemInHand(InteractionHand.MAIN_HAND,held);f.cloth.priceTag.setFilter(ItemStack.EMPTY);f.cloth.useShop(f.player);h.assertTrue(f.player.getMainHandItem()==held,"Missing price does not erase existing list");f.cloth.priceTag.setFilter(new ItemStack(Items.DIAMOND));var data=ShoppingListItem.getList(held);ShoppingListItem.saveList(held,new ShoppingListItem.ShoppingList(data.purchases(),data.shopOwner(),UUID.randomUUID()),"Shop");h.assertFalse(ShopTrade.purchase(f.player,f.ticker),"Wrong network refused");h.assertValueEqual(payments(f),0,"Wrong network cannot collect money");h.assertValueEqual(f.barrel.getItem(0).getCount(),32,"Wrong network cannot dispatch stock");h.succeed();
    }
}
